// Works out which days a run should check.
//
// This file has no imports so the same text can be pasted into an n8n Code
// node unchanged.

const DAYS_TO_CHECK_DEFAULTS = {
  // After a gap, look back at most this many days.
  maxCatchUpDays: 7,
  timezone: 'Asia/Manila',
};

function shiftDay(day, offset) {
  const moved = new Date(Date.parse(`${day}T00:00:00.000Z`) + offset * 24 * 60 * 60 * 1000);
  return moved.toISOString().slice(0, 10);
}

/**
 * @param lastCoveredDay  the latest day (YYYY-MM-DD) a successful run has
 *                        covered, or null when there is no run history.
 * @param now             the moment of the run.
 * @param settings        overrides for DAYS_TO_CHECK_DEFAULTS.
 * @returns               days (YYYY-MM-DD), oldest first. Every day after the
 *                        last covered day up to yesterday, capped at the most
 *                        recent maxCatchUpDays. Always at least yesterday, so
 *                        a second run on the same day rechecks it.
 */
function daysToCheck(lastCoveredDay, now, settings) {
  const config = { ...DAYS_TO_CHECK_DEFAULTS, ...settings };
  const today = new Intl.DateTimeFormat('en-CA', {
    timeZone: config.timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date(now));
  const yesterday = shiftDay(today, -1);

  if (!lastCoveredDay || lastCoveredDay >= yesterday) return [yesterday];

  const days = [];
  for (let day = yesterday; day > lastCoveredDay && days.length < config.maxCatchUpDays; day = shiftDay(day, -1)) {
    days.unshift(day);
  }
  return days;
}

/**
 * @param runRows  the rows of the run-history tab, each with a `days_covered`
 *                 text such as "2026-10-01, 2026-10-02".
 * @returns        the latest day any successful run covered, or null.
 */
function lastCoveredDay(runRows) {
  let latest = null;
  for (const row of runRows) {
    const days = typeof row.days_covered === 'string' ? row.days_covered.match(/\d{4}-\d{2}-\d{2}/g) : null;
    for (const day of days ?? []) {
      if (latest === null || day > latest) latest = day;
    }
  }
  return latest;
}

// Lets the tests load this file; has no effect inside an n8n Code node.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { daysToCheck, lastCoveredDay, DAYS_TO_CHECK_DEFAULTS };
}

// ---- n8n glue: reads this node's input and returns its output ----
const now = new Date();
const days = daysToCheck(lastCoveredDay($input.all().map((item) => item.json)), now);
// The time tracker stores each day as midnight in Manila (UTC+8).
const startOfDay = (day) => new Date(day + 'T00:00:00+08:00').toISOString();
return [
  {
    json: {
      runAt: now.toISOString(),
      days,
      startDate: startOfDay(days[0]),
      endDate: startOfDay(days[days.length - 1]),
    },
  },
];

// Checks that each time tracker response has the shape the workflow relies on.
// Each check throws an Error naming the endpoint and the missing field, which
// stops the run before anything is written or sent.
//
// This file has no imports so the same text can be pasted into an n8n Code
// node unchanged.

function isMissing(value) {
  return value === undefined || value === null;
}

function isObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// Reads a dotted path such as "user._id".
function readPath(object, path) {
  return path.split('.').reduce((value, part) => (isObject(value) ? value[part] : undefined), object);
}

function requireFields(endpoint, label, object, fields) {
  for (const field of fields) {
    if (isMissing(readPath(object, field))) {
      throw new Error(`${endpoint} response: ${label} is missing "${field}"`);
    }
  }
}

function requirePage(endpoint, body, paginationFields, itemFields) {
  if (!isObject(body) || !Array.isArray(body.items)) {
    throw new Error(`${endpoint} response: missing the "items" list`);
  }
  if (!isObject(body.pagination)) {
    throw new Error(`${endpoint} response: missing "pagination"`);
  }
  for (const field of paginationFields) {
    if (typeof body.pagination[field] !== 'number') {
      throw new Error(`${endpoint} response: missing "pagination.${field}"`);
    }
  }
  body.items.forEach((item, index) => requireFields(endpoint, `item ${index + 1}`, item, itemFields));
}

// POST /api/auth/login. The account must be read-only, so the workflow never
// runs with a login that could change anything.
function checkLogin(body) {
  if (!isObject(body) || body.success !== true) {
    throw new Error('Login response: "success" is not true');
  }
  if (!isObject(body.data) || !isObject(body.data.user)) {
    throw new Error('Login response: missing "data.user"');
  }
  const role = body.data.user.role;
  if (role !== 'readonly') {
    throw new Error(`Login response: the account's role is "${role}", but it must be "readonly"`);
  }
}

// GET /api/admin/time/logs. clockOut is not required: it is null on an open entry.
function checkTimeLogs(body) {
  requirePage(
    'Time logs',
    body,
    ['total', 'page', 'pages'],
    ['_id', 'user', 'user._id', 'date', 'clockIn', 'hours', 'breakHours', 'status'],
  );
}

// GET /api/pto/all
function checkPtoRequests(body) {
  requirePage(
    'PTO requests',
    body,
    ['currentPage', 'totalPages', 'totalItems', 'itemsPerPage'],
    ['_id', 'date', 'hours', 'status', 'createdAt', 'userId', 'userId._id'],
  );
}

// GET /api/admin/users
function checkUsers(body) {
  if (!Array.isArray(body)) {
    throw new Error('Users response: expected a list of users');
  }
  if (body.length === 0) {
    throw new Error('Users response: the list is empty');
  }
  body.forEach((user, index) =>
    requireFields('Users', `item ${index + 1}`, user, ['_id', 'firstName', 'lastName', 'email', 'role', 'createdAt']),
  );
}

// Lets the tests load this file; has no effect inside an n8n Code node.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { checkLogin, checkTimeLogs, checkPtoRequests, checkUsers };
}

// ---- n8n glue: reads this node's input and returns its output ----
const response = $input.first().json;
checkLogin(response.body);
const cookies = [].concat((response.headers ?? {})['set-cookie'] ?? []);
const token = cookies.map((cookie) => String(cookie).split(';')[0]).find((cookie) => cookie.startsWith('token='));
if (!token) {
  throw new Error('Login response: no "token" cookie was set');
}
return [{ json: { cookie: token } }];

